import { getLeadFieldValue } from '../../adapters/tableRecordsAdapter';

const EXCLUDED_COLUMN_KEYS = new Set(['select', 'actions', 'row_index']);

export function buildTemplateColumnOptions(columnsMeta = []) {
  return (columnsMeta ?? [])
    .filter((column) => column?.key && !EXCLUDED_COLUMN_KEYS.has(column.key))
    .map((column) => ({
      value: column.key,
      label:
        column.header
        ?? column.fieldMeta?.alias_name
        ?? column.fieldMeta?.key_name
        ?? column.key,
      keyName: column.fieldMeta?.key_name ?? column.key,
    }));
}

export function resolveRowColumnValue(row, columnKey, columnsMeta = []) {
  if (!row || !columnKey) return '';

  if (row[columnKey] != null && row[columnKey] !== '') {
    return String(row[columnKey]);
  }

  const column = (columnsMeta ?? []).find((item) => item?.key === columnKey);
  const fieldKey = column?.fieldMeta?.key_name ?? columnKey;
  const rawLead = row._rawLead ?? row;
  const fromLead = getLeadFieldValue(rawLead, fieldKey);
  if (fromLead != null && fromLead !== '') {
    return String(fromLead);
  }

  return '';
}
