import React, { useMemo, useState } from 'react';
import { Box, Grid, TextField, Typography } from '@mui/material';
import SearchableDropdown from '../../../../components/FlowBuilder/Common/SearchableDropdown/SearchableDropdown.tsx';
import CampaignAssignedDropdown from '../../../../components/Shared/CampaignAssignmentDropdown/index.tsx';
import { Button, Dialog } from '../../../../components/ui';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { recordService } from '../services/recordService';
import { RECORD_COPY } from '../constants/recordCopy';
import { normalizeFormItems } from '../utils/dynamicFilterUtils';

function mapFormsToOptions(formsObj = {}) {
  return Object.values(formsObj).map((form) => ({
    label: form.leads_form_name,
    value: form.leads_form_id,
    ...form,
  }));
}

function mapFormItemsToOptions(items) {
  return normalizeFormItems(items)
    .sort((a, b) => (a.order_id ?? 0) - (b.order_id ?? 0))
    .map((item) => ({
      label: item.alias_name || item.key_name,
      value: item.key_name,
      ...item,
    }));
}

function filterMappableFormItems(items = []) {
  return items.filter(
    (item) =>
      !item?.is_static_column
      && item?.statusOption !== 'is_status'
      && item?.statusOption !== 'is_sub_status'
      && item?.key_name !== 'lead_id'
  );
}

export default function BulkMoveModal({
  open,
  onClose,
  workspaceId,
  workspaceName,
  table,
  formItems,
  selectedLeadIds = [],
  organisationId,
  onSuccess,
}) {
  const { showSnackBar } = useSnackBar();
  const [targetCampaign, setTargetCampaign] = useState(null);
  const [targetForm, setTargetForm] = useState(null);
  const [targetForms, setTargetForms] = useState([]);
  const [targetFormItems, setTargetFormItems] = useState([]);
  const [selectedTargetFormItems, setSelectedTargetFormItems] = useState([]);
  const [loadingForms, setLoadingForms] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const currentFormItems = useMemo(
    () => filterMappableFormItems(mapFormItemsToOptions(formItems)),
    [formItems]
  );

  const resetTargetState = () => {
    setTargetCampaign(null);
    setTargetForm(null);
    setTargetForms([]);
    setTargetFormItems([]);
    setSelectedTargetFormItems([]);
  };

  const handleClose = () => {
    resetTargetState();
    onClose?.();
  };

  const handleTargetCampaignChange = async (campaign) => {
    setTargetCampaign(campaign);
    setTargetForm(null);
    setTargetFormItems([]);
    setTargetForms([]);
    setSelectedTargetFormItems([]);

    if (!campaign?.proposal_id) return;

    setLoadingForms(true);
    try {
      const forms = await recordService.fetchFormsByCampaignId(campaign.proposal_id);
      setTargetForms(mapFormsToOptions(forms));
    } catch {
      showSnackBar('Failed to load target forms', 'error');
    } finally {
      setLoadingForms(false);
    }
  };

  const handleTargetFormChange = (form) => {
    setTargetForm(form);
    setSelectedTargetFormItems([]);

    if (form?.leads_form_items) {
      setTargetFormItems(filterMappableFormItems(mapFormItemsToOptions(form.leads_form_items)));
    } else {
      setTargetFormItems([]);
    }
  };

  const handleMove = async () => {
    if (!targetCampaign || !targetForm) {
      showSnackBar('Please select target campaign and form', 'error');
      return;
    }

    if (!selectedLeadIds.length) {
      showSnackBar('No records selected', 'warning');
      return;
    }

    const keyMapping = {};
    currentFormItems.forEach((item, index) => {
      const targetItem = selectedTargetFormItems[index];
      if (targetItem?.key_name) {
        keyMapping[item.key_name] = targetItem.key_name;
      }
    });

    setIsSubmitting(true);
    try {
      const res = await recordService.moveRecords({
        lead_ids: selectedLeadIds,
        campaign_id: targetCampaign.proposal_id,
        lead_form_id: String(targetForm.value ?? targetForm.leads_form_id),
        key_mapping: keyMapping,
      });

      if (res?.status === 200 || res?.status === true) {
        showSnackBar(RECORD_COPY.success.moved, 'success');
        onSuccess?.();
        handleClose();
      } else {
        showSnackBar('Failed to move records', 'error');
      }
    } catch {
      showSnackBar('Failed to move records', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      title={RECORD_COPY.bulk.moveTitle}
      subtitle={RECORD_COPY.bulk.moveSubtitle}
      maxWidth="md"
      actions={
        <>
          <Button variant="ghost" onClick={handleClose} disabled={isSubmitting}>
            {RECORD_COPY.deleteConfirm.cancel}
          </Button>
          <Button variant="primary" loading={isSubmitting} onClick={handleMove}>
            {RECORD_COPY.bulk.moveConfirm}
          </Button>
        </>
      }
    >
      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Typography variant="subtitle2" sx={{ mb: 1 }}>
            {RECORD_COPY.bulk.currentCampaign}
          </Typography>
          <TextField
            fullWidth
            size="small"
            value={workspaceName || workspaceId || ''}
            disabled
          />

          <Box sx={{ mt: 2 }}>
            <TextField
              fullWidth
              size="small"
              label={RECORD_COPY.bulk.currentForm}
              value={table?.name || ''}
              disabled
            />
          </Box>

          <Box sx={{ mt: 2, display: 'flex', flexDirection: 'column', gap: 2 }}>
            {currentFormItems.map((item) => (
              <TextField
                key={item.key_name}
                fullWidth
                size="small"
                label={item.alias_name || item.key_name}
                value={item.alias_name || item.key_name}
                disabled
              />
            ))}
          </Box>
        </Grid>

        <Grid item xs={12} md={6}>
          <Typography variant="subtitle2" sx={{ mb: 1 }}>
            {RECORD_COPY.bulk.targetCampaign}
          </Typography>
          <CampaignAssignedDropdown
            value={targetCampaign}
            onChange={handleTargetCampaignChange}
            organisationId={organisationId}
            label={RECORD_COPY.bulk.targetCampaign}
          />

          <Box sx={{ mt: 2 }}>
            <SearchableDropdown
              size="small"
              label={RECORD_COPY.bulk.targetForm}
              options={targetForms}
              value={targetForm}
              onChange={handleTargetFormChange}
              disabled={!targetCampaign || loadingForms}
              labelKey="label"
              valueKey="value"
            />
          </Box>

          <Box sx={{ mt: 2, display: 'flex', flexDirection: 'column', gap: 2 }}>
            {currentFormItems.map((item, index) => (
              <SearchableDropdown
                key={item.key_name}
                size="small"
                label={`${RECORD_COPY.bulk.mapField} ${item.alias_name || item.key_name}`}
                options={targetFormItems}
                value={selectedTargetFormItems[index] || null}
                onChange={(selected) => {
                  setSelectedTargetFormItems((prev) => {
                    const next = [...prev];
                    next[index] = selected;
                    return next;
                  });
                }}
                disabled={!targetForm}
                labelKey="label"
                valueKey="value"
              />
            ))}
          </Box>
        </Grid>
      </Grid>
    </Dialog>
  );
}
