import React from 'react';
import { Box } from '@mui/material';
import { LeadChatSocketProvider } from '../sockets/LeadChatSocketProvider';
import useLeadChatSession from '../hooks/useLeadChatSession';
import useLeadChatScroll from '../hooks/useLeadChatScroll';
import useLeadChatSx from '../hooks/useLeadChatSx';
import LeadChatHeader from './LeadChatHeader';
import LeadChatBotSelect from './LeadChatBotSelect';
import LeadChatSessionBanner from './LeadChatSessionBanner';
import LeadChatMessageFeed from './LeadChatMessageFeed';
import LeadChatComposer from './LeadChatComposer';

export default function LeadChatPanelContent({
  open,
  baseContext,
  formPayload,
  onClose,
  canSendTemplate = false,
  onOpenSendTemplate,
}) {
  const sx = useLeadChatSx();

  const session = useLeadChatSession({
    open,
    baseContext,
    formPayload,
    onClose,
  });

  const {
    state,
    chatContext,
    agentName,
    currentUserId,
    dispatch,
    handleBotChange,
    handleSocketPayload,
    loadOlderMessages,
    handleSendMessage,
    toggleSession,
    shouldStickToBottomRef,
  } = session;

  const { scrollRef, handleScroll } = useLeadChatScroll({
    messages: state.messages,
    isLoadingMessages: state.ui.isLoading,
    isLoadingOlder: state.ui.isLoadingOlder,
    hasMoreMessages: state.pagination.hasMore,
    onLoadOlderMessages: loadOlderMessages,
    shouldStickToBottomRef,
    activePhone: chatContext?.phoneNumber,
  });

  if (!open || !baseContext) return null;

  const panel = (
    <Box sx={sx.body}>
      <LeadChatHeader
        conversation={state.conversation}
        userDetail={state.conversation.userDetail}
        currentUserId={currentUserId}
        onClose={onClose}
        onToggleSession={toggleSession}
      />

      <LeadChatBotSelect
        organisationId={baseContext.organisationId}
        botNumber={state.conversation.botNumber}
        showSelector={state.bot.showSelector}
        isResolving={state.ui.isResolvingBot}
        onBotChange={handleBotChange}
      />

      <LeadChatSessionBanner
        composerMode={state.ui.composerMode}
        userDetail={state.conversation.userDetail}
        canSendTemplate={canSendTemplate}
        onStartSession={toggleSession}
        onOpenSendTemplate={onOpenSendTemplate}
      />

      <LeadChatMessageFeed
        scrollRef={scrollRef}
        onScroll={handleScroll}
        messages={state.messages}
        isLoading={state.ui.isResolvingBot || state.ui.isLoading}
        isLoadingOlder={state.ui.isLoadingOlder}
      />

      <LeadChatComposer
        draft={state.ui.draft}
        onDraftChange={(value) => dispatch({ type: 'SET_DRAFT', payload: value })}
        isSending={state.ui.isSending}
        composerMode={state.ui.composerMode}
        canSendTemplate={canSendTemplate}
        onSendMessage={handleSendMessage}
        onOpenSendTemplate={onOpenSendTemplate}
        shouldStickToBottomRef={shouldStickToBottomRef}
      />
    </Box>
  );

  if (!chatContext?.botNumber) {
    return panel;
  }

  return (
    <LeadChatSocketProvider
      organisationId={chatContext.organisationId}
      botNumber={chatContext.botNumber}
      phoneNumber={chatContext.phoneNumber}
      agentName={agentName}
      onPayload={handleSocketPayload}
    >
      {panel}
    </LeadChatSocketProvider>
  );
}
